refentry.refsect1:
&reftitle.description;
public mixedPDOStatement::fetch intmodePDO::FETCH_DEFAULT intcursorOrientationPDO::FETCH_ORI_NEXT intcursorOffset0
Busca uma linha de um conjunto de resultados associado a uma instância de PDOStatement. O parâmetro mode determina como o PDO retorna a linha.

&reftitle.returnvalues;

 O valor de retorno desta função em caso de sucesso depende do tipo de busca. Em
 todos os casos, &false; é retornado em caso de falha ou se não houver mais linhas.

  &reftitle.examples;

   Busca de linhas usando diferentes estilos de busca


<?php
$db = new PDO('sqlite::memory:');
$db->exec("CREATE TABLE fruit (name VARCHAR(100), colour VARCHAR(100))");
$db->exec("INSERT INTO fruit (name, colour) VALUES
                             ('apple', 'red'),
                             ('banana', 'yellow'),
                             ('orange', 'orange'),
                             ('kiwi', 'green')");
$sth = $db->prepare("SELECT name, colour FROM fruit");
$sth->execute();

/* Exercita estilos de PDOStatement::fetch */
echo "PDO::FETCH_ASSOC: ";
echo "Retorna a próxima linha como um array indexado por nome de coluna\n";
$result = $sth->fetch(PDO::FETCH_ASSOC);
var_dump($result);
echo "\n";

echo "PDO::FETCH_BOTH: ";
echo "Retorna a próxima linha como um array indexado por nome de coluna e número\n";
$result = $sth->fetch(PDO::FETCH_BOTH);
var_dump($result);
echo "\n";

echo "PDO::FETCH_LAZY: ";
echo "Retorna a próxima linha como um objeto PDORow com nomes de colunas como propriedades\n";
$result = $sth->fetch(PDO::FETCH_LAZY);
var_dump($result);
echo "\n";

echo "PDO::FETCH_OBJ: ";
echo "Retorna a próxima linha como um objeto stdClass com nomes de colunas como propriedades\n";
$result = $sth->fetch(PDO::FETCH_OBJ);
var_dump($result);
echo "\n";
?>


    &example.outputs;


PDO::FETCH_ASSOC: Retorna a próxima linha como um array indexado por nome de coluna
array(2) {
  ["name"]=>
  string(5) "apple"
  ["colour"]=>
  string(3) "red"
}

PDO::FETCH_BOTH: Retorna a próxima linha como um array indexado por nome de coluna e número
array(4) {
  ["name"]=>
  string(6) "banana"
  [0]=>
  string(6) "banana"
  ["colour"]=>
  string(6) "yellow"
  [1]=>
  string(6) "yellow"
}

PDO::FETCH_LAZY: Retorna a próxima linha como um objeto PDORow com nomes de colunas como propriedades
object(PDORow)#3 (3) {
  ["queryString"]=>
  string(30) "SELECT name, colour FROM fruit"
  ["name"]=>
  string(6) "orange"
  ["colour"]=>
  string(6) "orange"
}

PDO::FETCH_OBJ: Retorna a próxima linha como um objeto stdClass com nomes de colunas como propriedades
object(stdClass)#4 (2) {
  ["name"]=>
  string(4) "kiwi"
  ["colour"]=>
  string(5) "green"
}





   Busca de linhas com um cursor rolável


<?php
function readDataForwards($dbh) {
    $sql = 'SELECT hand, won, bet FROM mynumbers ORDER BY BET';
    $stmt = $dbh->prepare($sql, array(PDO::ATTR_CURSOR => PDO::CURSOR_SCROLL));
    $stmt->execute();
    while ($row = $stmt->fetch(PDO::FETCH_NUM, PDO::FETCH_ORI_NEXT)) {
        $data = $row[0] . "\t" . $row[1] . "\t" . $row[2] . "\n";
        print $data;
    }
}
function readDataBackwards($dbh) {
    $sql = 'SELECT hand, won, bet FROM mynumbers ORDER BY bet';
    $stmt = $dbh->prepare($sql, array(PDO::ATTR_CURSOR => PDO::CURSOR_SCROLL));
    $stmt->execute();
    $row = $stmt->fetch(PDO::FETCH_NUM, PDO::FETCH_ORI_LAST);
    do {
        $data = $row[0] . "\t" . $row[1] . "\t" . $row[2] . "\n";
        print $data;
    } while ($row = $stmt->fetch(PDO::FETCH_NUM, PDO::FETCH_ORI_PRIOR));
}

print "Lendo para a frente:\n";
readDataForwards($conn);

print "Lendo para trás:\n";
readDataBackwards($conn);
?>


    &example.outputs;


Reading forwards:
21    10    5
16    0     5
19    20    10

Reading backwards:
19    20    10
16    0     5
21    10    5





   Construction order

    Quando objetos são buscados através de PDO::FETCH_CLASS, as propriedades
    do objeto são atribuídas primeiro, e depois o construtor da classe é
    invocado. Entretanto, quando PDO::FETCH_PROPS_LATE também for informada,
    esta ordem é revertida, isto, é, primeiro o construtor é chamado, e
    depois as propriedades são atribuídas.



<?php
class Person
{
    private $name;

    public function __construct()
    {
        $this->tell();
    }

    public function tell()
    {
        if (isset($this->name)) {
            echo "Eu sou {$this->name}.\n";
        } else {
            echo "Eu não tenho um nome ainda.\n";
        }
    }
}

$sth = $dbh->query("SELECT * FROM people");
$sth->setFetchMode(PDO::FETCH_CLASS, 'Person');
$person = $sth->fetch();
$person->tell();
$sth->setFetchMode(PDO::FETCH_CLASS|PDO::FETCH_PROPS_LATE, 'Person');
$person = $sth->fetch();
$person->tell();
?>


    &example.outputs.similar;


Eu sou Alice.
Eu sou Alice.
Eu não tenho um nome ainda.
Eu sou Bob.
